agent/controller.py:
"""Deterministic Controller: validates every model proposal and drives D1-D9.

The Controller is the trust gate between the (untrusted) model and the trusted
orchestrator. It NEVER executes model text; it only builds a schema-valid
ToolCall from a fully-validated proposal and calls Orchestrator.run_tool_call.
It enforces budgets, duplicate detection, revision checks and workflow gates.
It never edits effects to get past a D4 DENY.
"""
from __future__ import annotations

import copy
import time
import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Dict, List, Mapping, Optional, Tuple

from .config import AgentConfig


class ControllerReject(Exception):
    """A proposal was rejected deterministically (fed back to the model, not executed)."""
    def __init__(self, code: str, message: str):
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


@dataclass
class Budget:
    cfg: AgentConfig
    started: float = field(default_factory=time.monotonic)
    iterations: int = 0
    tool_calls: int = 0
    tokens: int = 0

    def tick_iteration(self) -> None:
        self.iterations += 1

    def exhausted(self) -> Optional[str]:
        if self.tokens >= self.cfg.max_tokens:
            return "max_tokens"
        if self.iterations >= self.cfg.max_iterations:
            return "max_iterations"
        if self.tool_calls >= self.cfg.max_tool_calls:
            return "max_tool_calls"
        if time.monotonic() - self.started >= self.cfg.wall_clock_s:
            return "wall_clock"
        return None


class Controller:
    def __init__(self, registry, orchestrator, cfg: AgentConfig):
        self._registry = registry
        self._orch = orchestrator
        self._cfg = cfg
        self._denied_tools = set()
        self._seen_toolcalls: set[str] = set()

    # -- validation ---------------------------------------------------------
    def validate(self, proposal: Mapping[str, Any], state: Mapping[str, Any]) -> Dict[str, Any]:
        """Raise ControllerReject on any problem; else return the normalized proposal."""
        from .schema import validate_shape
        proposal = validate_shape(dict(proposal))
        if proposal["case_id"] != state["case_id"]:
            raise ControllerReject("CASE_MISMATCH", "case_id does not match the case")
        current_rev = state.get("revision", 1)
        if proposal["case_revision"] != current_rev:
            raise ControllerReject("CASE_REVISION_STALE",
                                   f"case_revision {proposal['case_revision']} != current {current_rev}")
        # Evidence refs must exist.
        known = {e.get("evidence_id") for e in state.get("evidence", [])}
        missing = [r for r in proposal.get("evidence_refs", []) if r not in known]
        if missing:
            raise ControllerReject("EVIDENCE_UNKNOWN", f"unknown evidence_refs: {missing}")

        unknowns = {u.get("facet") for u in state.get("residual_unknowns", [])}
        if set(proposal["unknowns_targeted"]) - unknowns:
            raise ControllerReject("UNKNOWN_FACET", "unknowns_targeted must name residual_unknowns facets")
        from orchestrator.workflow import WorkflowEngine
        static = [e for e in state.get("evidence", [])
                  if str(e.get("facet", "")).startswith("static.") and e.get("status") == "SUCCESS"]
        digest = (state.get("target_ref", {}).get("verified_digest") or {}).get("value")
        reputation = self._cfg.known_reputations.get(digest, "UNAVAILABLE")
        if reputation not in {"KNOWN_BENIGN", "KNOWN_MALICIOUS", "UNKNOWN", "UNAVAILABLE", "CONFLICT"}:
            reputation = "UNAVAILABLE"
        known_fresh = reputation in {"KNOWN_BENIGN", "KNOWN_MALICIOUS"}
        gate = WorkflowEngine().decide(state, phase="STATIC" if static else "REPUTATION",
                                      reputation=reputation, reputation_fresh_and_consistent=known_fresh,
                                      dynamic_needed=proposal["action"] == "REQUEST_DYNAMIC_ANALYSIS")
        if proposal["action"] == "REQUEST_DYNAMIC_ANALYSIS" and gate["next_step"] != "HUMAN_REVIEW":
            raise ControllerReject("STATIC_FIRST", "Static evidence required before escalation")
        if proposal["action"] == "FINISH" and not static and not known_fresh and not self._seen_toolcalls:
            raise ControllerReject("STATIC_FIRST", "Unknown reputation requires an approved static follow-up before assessment")
        if proposal["action"] == "FINISH" and proposal["finding"]["verdict"] not in ("UNKNOWN", "INSUFFICIENT_EVIDENCE"):
            expected = {"KNOWN_BENIGN": "BENIGN", "KNOWN_MALICIOUS": "MALICIOUS"}.get(reputation)
            cited = [e for e in state.get("evidence", []) if e.get("evidence_id") in proposal["evidence_refs"]]
            if not known_fresh or proposal["finding"]["verdict"] != expected or not any(
                    e.get("facet") == "sha256" and e.get("status") == "SUCCESS" and e.get("value") == digest for e in cited):
                raise ControllerReject("INSUFFICIENT_EVIDENCE", "Substantive verdict requires trusted hash reputation and successful digest citation")
        if proposal["action"] in ("FINISH", "REQUEST_DYNAMIC_ANALYSIS"):
            return dict(proposal)

        # TOOL_CALL: verify the tool against the live registry.
        tool = proposal["tool"]
        tid, tver, pid = tool["tool_id"], tool["tool_version"], tool["provider_id"]
        if (tid, tver, pid) in self._denied_tools:
            raise ControllerReject("TOOL_PREVIOUSLY_DENIED", "Policy denial cannot be retried with altered arguments")
        try:
            spec = self._registry.get_tool(tid, tver, require_enabled=True)
        except Exception as exc:
            raise ControllerReject("TOOL_UNKNOWN", f"tool not registered/enabled: {exc}")
        if spec["provider"]["id"] != pid:
            raise ControllerReject("PROVIDER_MISMATCH",
                                   f"provider {pid} != registered {spec['provider']['id']}")
        if state["target_ref"]["kind"] not in spec.get("supported_targets", []):
            raise ControllerReject("TARGET_UNSUPPORTED", "tool does not support this target kind")
        # Workflow gate (ADR-001): foreign-code/dynamic tools are not run on host;
        # the model must use REQUEST_DYNAMIC_ANALYSIS instead.
        if spec.get("effects", {}).get("executes_foreign_code"):
            raise ControllerReject("DYNAMIC_NOT_ALLOWED",
                                   "foreign-code tool requires REQUEST_DYNAMIC_ANALYSIS, not TOOL_CALL")
        # Duplicate detection.
        key = self._toolcall_key(tid, tver, pid, tool.get("arguments", {}),
                                 state["target_ref"])
        if key in self._seen_toolcalls:
            raise ControllerReject("DUPLICATE_TOOL_CALL", "this exact tool call was already attempted")
        if not str(spec.get("capability", "")).startswith("static.") or any(
                spec.get("effects", {}).get(k) for k in ("mutates_target", "requires_human_approval")):
            raise ControllerReject("WORKFLOW_GATE", "Only static follow-ups are enabled")
        from orchestrator.input_validator import validate_tool_call, ValidationError
        try:
            validate_tool_call(self._build_toolcall(tool, state), spec, state)
        except ValidationError as exc:
            raise ControllerReject(exc.code, exc.message) from exc
        return dict(proposal)

    # -- execution ----------------------------------------------------------
    def run_tool(self, proposal: Mapping[str, Any], state: Mapping[str, Any], case_path, remaining_s=None) -> Any:
        tool = proposal["tool"]
        call = self._build_toolcall(tool, state)
        if remaining_s is not None:
            if remaining_s < 0.001:
                raise ControllerReject("DEADLINE", "No execution time remains")
            call["budget"]["timeout_ms"] = min(call["budget"]["timeout_ms"], max(1, int(remaining_s * 1000)))
        key = self._toolcall_key(tool["tool_id"], tool["tool_version"], tool["provider_id"],
                                 tool.get("arguments", {}), state["target_ref"])
        self._seen_toolcalls.add(key)
        record = self._orch.run_tool_call(call, case_path)
        if record.outcome == "DENY":
            self._denied_tools.add((tool["tool_id"], tool["tool_version"], tool["provider_id"]))
        return record

    def _build_toolcall(self, tool: Mapping[str, Any], state: Mapping[str, Any]) -> Dict[str, Any]:
        spec = self._registry.get_tool(tool["tool_id"], tool["tool_version"], require_enabled=True)
        limits = spec["limits"]
        budget = {"timeout_ms": min(30000, limits["timeout_ms"]),
                  "max_output_bytes": min(200000, limits["max_output_bytes"])}
        return {
            "schema_version": "d0-v1",
            "call_id": "CALL-agent-" + uuid.uuid4().hex[:16],
            "case_id": state["case_id"],
            "expected_revision": state.get("revision", 1),
            "tool_id": tool["tool_id"], "tool_version": tool["tool_version"],
            "provider_id": tool["provider_id"],
            "target_ref": copy.deepcopy(state["target_ref"]),
            "arguments": copy.deepcopy(tool.get("arguments", {})),
            "reason": "agent-proposed investigation step",
            "requested_by": "agent",
            "requested_at": datetime.now(timezone.utc).isoformat(),
            "budget": budget,
        }

    @staticmethod
    def _toolcall_key(tid, tver, pid, args, target_ref) -> str:
        import json
        return json.dumps([tid, tver, pid, args, target_ref.get("observed")],
                          sort_keys=True, ensure_ascii=False)

agent/planner.py:
"""Planner interface + local local Qwen (Ollama) and deterministic Mock planners.

The planner returns the model's RAW text; the Controller parses/validates it.
The planner never executes anything and talks only to the local Ollama loopback
endpoint. On any model/transport error it raises PlannerError and NEVER silently
falls back to a different model.
"""
from __future__ import annotations

import json
import time
import urllib.request
from typing import Any, Dict, List, Mapping, Optional, Protocol

from .config import AgentConfig
from .schema import OLLAMA_FORMAT_SCHEMA


class PlannerError(Exception):
    """Model/transport failure. Treated as an error, never as a benign result."""


class Planner(Protocol):
    def decide(self, context: Mapping[str, Any]) -> "PlanResult": ...


class PlanResult:
    def __init__(self, raw: str, latency_s: float, meta: Optional[Dict[str, Any]] = None):
        self.raw = raw
        self.latency_s = latency_s
        self.meta = meta or {}


class _RejectRedirects(urllib.request.HTTPRedirectHandler):
    """Schema-aware evaluation calls never follow an endpoint redirect."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Refuse before urllib can construct a request to the redirect target.
        raise PlannerError("Ollama redirects are forbidden")


class OllamaPlanner:
    """Local local Qwen via Ollama /api/chat with JSON-schema-constrained output."""

    def __init__(self, cfg: AgentConfig):
        if not cfg.is_local_loopback():
            raise PlannerError("Ollama host must be a local loopback address")
        self._cfg = cfg

    def decide(self, context: Mapping[str, Any]) -> PlanResult:
        # Frozen v1 request contract and transport behaviour remain the default.
        return self._decide(context, OLLAMA_FORMAT_SCHEMA)

    def decide_with_schema(self, context: Mapping[str, Any], format_schema: Mapping[str, Any]) -> PlanResult:
        """Explicit schema transport for v2; fail closed before any HTTP object/IO.

        Check the actual config again at the send boundary, including configs
        constructed without __post_init__ or mutated after planner construction.
        Use the trusted implementation, not a caller-supplied validator override.
        """
        try:
            local = AgentConfig.is_local_loopback(self._cfg)
        except (ValueError, TypeError, AttributeError):
            local = False
        if not local:
            raise PlannerError("Ollama host must be a local loopback address")
        return self._decide(context, format_schema, reject_redirects=True)

    def _decide(self, context: Mapping[str, Any], format_schema: Mapping[str, Any],
                *, reject_redirects: bool = False) -> PlanResult:
        cfg = self._cfg
        body = {
            "model": cfg.model,
            "messages": [
                {"role": "system", "content": context["system"] + "\nRequired output contract: " + json.dumps(format_schema)},
                {"role": "user", "content": context["user"]},
            ],
            "stream": False,
            "think": cfg.think,
            "format": format_schema,   # constrained decoding when supported
            "options": {"temperature": cfg.temperature, "seed": 42, "num_predict": min(cfg.num_predict, context.get("output_token_limit", cfg.num_predict)), "num_ctx": 8192},
        }
        req = urllib.request.Request(
            cfg.ollama_host.rstrip("/") + "/api/chat",
            data=json.dumps(body).encode("utf-8"),
            headers={"Content-Type": "application/json"})
        t0 = time.time()
        try:
            handlers = [urllib.request.ProxyHandler({})]
            if reject_redirects:
                handlers.append(_RejectRedirects())
            with urllib.request.build_opener(*handlers).open(req, timeout=min(cfg.inference_timeout_s, context.get("remaining_s", cfg.inference_timeout_s))) as resp:
                payload = json.loads(resp.read().decode("utf-8"))
        except Exception as exc:  # transport/timeout/http
            raise PlannerError(f"Ollama inference failed: {type(exc).__name__}: {exc}") from exc
        latency = round(time.time() - t0, 2)
        content = (payload.get("message") or {}).get("content")
        if not isinstance(content, str) or not content.strip():
            raise PlannerError("Ollama returned empty content")
        return PlanResult(content, latency, {"model": cfg.model, "think": cfg.think,
                                             "eval_count": payload.get("eval_count"), "prompt_eval_count": payload.get("prompt_eval_count"), "done_reason": payload.get("done_reason")})


class MockPlanner:
    """MOCK_LLM planner for deterministic tests. NOT a real AI agent.

    Returns a fixed sequence of action JSON strings; raises if exhausted.
    """

    is_mock = True

    def __init__(self, scripted_actions: List[Dict[str, Any]]):
        self._queue = list(scripted_actions)
        self._i = 0

    def decide(self, context: Mapping[str, Any]) -> PlanResult:
        if self._i >= len(self._queue):
            raise PlannerError("MockPlanner script exhausted")
        action = dict(self._queue[self._i])
        self._i += 1
        # A realistic planner reads the current case_id/revision from the context;
        # the mock fills them so scripted actions stay revision-correct across turns.
        facts = context.get("facts", {})
        action.setdefault("case_id", facts.get("case_id"))
        action["case_id"] = facts.get("case_id", action.get("case_id"))
        action["case_revision"] = facts.get("case_revision", action.get("case_revision"))
        return PlanResult(json.dumps(action), 0.0, {"mock": True})

agent/schema.py:
"""Structured action contract for the investigation Agent.

The model proposes exactly one action per turn as JSON. This module parses and
shape-validates that JSON. Shape validity is necessary but NOT sufficient: the
Controller re-checks every id/revision/tool/param against the live system. The
model's text is data, never a command.
"""
from __future__ import annotations

import json
from typing import Any, Dict, Tuple

ACTIONS = ("TOOL_CALL", "FINISH", "REQUEST_DYNAMIC_ANALYSIS")
VERDICTS = ("MALICIOUS", "SUSPICIOUS", "BENIGN", "UNKNOWN", "INSUFFICIENT_EVIDENCE")

# JSON Schema handed to Ollama for constrained decoding (best-effort; re-validated here).
OLLAMA_FORMAT_SCHEMA: Dict[str, Any] = {
    "type": "object",
    "properties": {
        "action": {"type": "string", "enum": list(ACTIONS)},
        "reason": {"type": "string"},
        "evidence_refs": {"type": "array", "items": {"type": "string"}},
        "unknowns_targeted": {"type": "array", "items": {"type": "string"}},
        "case_id": {"type": "string"},
        "case_revision": {"type": "integer"},
        "tool": {
            "type": "object",
            "properties": {
                "tool_id": {"type": "string"},
                "tool_version": {"type": "string"},
                "provider_id": {"type": "string"},
                "arguments": {"type": "object"},
            },
        },
        "finding": {
            "type": "object",
            "properties": {
                "verdict": {"type": "string", "enum": list(VERDICTS)},
                "confidence": {"type": "number"},
                "rationale": {"type": "string"},
                "limitations": {"type": "array", "items": {"type": "string"}},
                # Optional (TASK 05B): the agent's alignment ASSESSMENT relative to the
                # authoritative static LightGBM prediction. The agent never overrides the
                # static label; this only records agreement + a suggested handling.
                "assessment": {
                    "type": "object",
                    "properties": {
                        "alignment": {"type": "string",
                                      "enum": ["CONSISTENT", "CONFLICT", "INSUFFICIENT_EVIDENCE"]},
                        "review_required": {"type": "boolean"},
                        "recommendation": {"type": "string",
                                           "enum": ["MANUAL_REVIEW", "MONITOR",
                                                    "AVOID_EXECUTION", "CONSIDER_QUARANTINE"]},
                        "explanation": {"type": "string"},
                    },
                    "additionalProperties": False,
                },
            },
        },
    },
    "required": ["action", "reason", "case_id", "case_revision"],
}


class ActionError(ValueError):
    """Raised when the model output cannot be parsed or fails shape validation."""


def parse_action(raw: str) -> Dict[str, Any]:
    """Parse the model's raw text into a JSON object. No code is ever executed."""
    if not isinstance(raw, str) or not raw.strip():
        raise ActionError("Empty model output")
    text = raw.strip()
    try:
        obj = json.loads(text)
    except (ValueError, TypeError) as exc:
        raise ActionError(f"Model output is not valid JSON: {exc}") from exc
    if not isinstance(obj, dict):
        raise ActionError("Model output JSON must be an object")
    return obj


def validate_shape(obj: Dict[str, Any]) -> Dict[str, Any]:
    """Validate the structural contract (not the live-system facts)."""
    from jsonschema import Draft202012Validator
    errors = list(Draft202012Validator(OLLAMA_FORMAT_SCHEMA).iter_errors(obj))
    if errors:
        raise ActionError(errors[0].message)
    action = obj.get("action")
    if action not in ACTIONS:
        raise ActionError(f"Unknown action: {action!r}")
    if not isinstance(obj.get("reason"), str) or not obj["reason"].strip():
        raise ActionError("reason is required")
    if not isinstance(obj.get("case_id"), str):
        raise ActionError("case_id is required")
    if type(obj.get("case_revision")) is not int:
        raise ActionError("case_revision must be an integer")
    for key in ("evidence_refs", "unknowns_targeted"):
        v = obj.get(key, [])
        if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
            raise ActionError(f"{key} must be a list of strings")
        obj.setdefault(key, [])

    if action == "TOOL_CALL":
        tool = obj.get("tool")
        if not isinstance(tool, dict):
            raise ActionError("TOOL_CALL requires a tool object")
        for f in ("tool_id", "tool_version", "provider_id"):
            if not isinstance(tool.get(f), str) or not tool[f]:
                raise ActionError(f"tool.{f} is required for TOOL_CALL")
        if not isinstance(tool.get("arguments", {}), dict):
            raise ActionError("tool.arguments must be an object")
        tool.setdefault("arguments", {})
    elif action == "FINISH":
        finding = obj.get("finding")
        if not isinstance(finding, dict):
            raise ActionError("FINISH requires a finding object")
        if finding.get("verdict") not in VERDICTS:
            raise ActionError("finding.verdict is invalid")
        conf = finding.get("confidence", 0.0)
        if not isinstance(conf, (int, float)) or isinstance(conf, bool) or not 0 <= conf <= 1:
            raise ActionError("finding.confidence must be between 0 and 1")
        if not isinstance(finding.get("rationale"), str) or not finding["rationale"].strip():
            raise ActionError("finding.rationale is required")
        finding.setdefault("limitations", [])
        if not isinstance(finding["limitations"], list) or any(not isinstance(x, str) for x in finding["limitations"]):
            raise ActionError("finding.limitations must be strings")
    # REQUEST_DYNAMIC_ANALYSIS needs only the common fields.
    return obj


def parse_and_validate(raw: str) -> Dict[str, Any]:
    return validate_shape(parse_action(raw))

# Constrain action-specific fields at decoding time as well as in Python.
OLLAMA_FORMAT_SCHEMA["required"] += ["evidence_refs", "unknowns_targeted"]
OLLAMA_FORMAT_SCHEMA["additionalProperties"] = False
for field, required in (("tool", ["tool_id", "tool_version", "provider_id", "arguments"]),
                        ("finding", ["verdict", "confidence", "rationale", "limitations"])):
    OLLAMA_FORMAT_SCHEMA["properties"][field]["required"] = required
    OLLAMA_FORMAT_SCHEMA["properties"][field]["additionalProperties"] = False

OLLAMA_FORMAT_SCHEMA["properties"]["evidence_refs"]["maxItems"] = 3

OLLAMA_FORMAT_SCHEMA["properties"]["case_revision"]["minimum"] = 1
OLLAMA_FORMAT_SCHEMA["properties"]["finding"]["properties"]["confidence"].update(minimum=0, maximum=1)
for key in ("case_id", "reason"):
    OLLAMA_FORMAT_SCHEMA["properties"][key]["minLength"] = 1
OLLAMA_FORMAT_SCHEMA["allOf"] = [
    {"if": {"properties": {"action": {"const": action}}},
     "then": {"required": required, "not": {"anyOf": [{"required": [f]} for f in forbidden]}}}
    for action, required, forbidden in (("TOOL_CALL", ["tool"], ["finding"]),
        ("FINISH", ["finding"], ["tool"]), ("REQUEST_DYNAMIC_ANALYSIS", [], ["tool", "finding"]))]

