"""Versioned action wrapper around the unchanged 06A assessment v2.1."""
import copy
import json
from jsonschema import Draft202012Validator, ValidationError
from evaluation.task06a.schema_v2 import OLLAMA_FORMAT_SCHEMA_V2

IDS = {"type": "array", "maxItems": 3, "uniqueItems": True, "items": {"type": "string", "minLength": 1}}
FORMAT = {"type": "object", "additionalProperties": False,
          "required": ["action", "case_id", "case_revision", "reason", "evidence_refs"],
          "properties": {
              "action": {"type": "string", "enum": ["TOOL_CALL", "FINISH", "REQUEST_MORE_EVIDENCE"]},
              "case_id": {"type": "string"}, "case_revision": {"type": "integer", "minimum": 1},
              "reason": {"type": "string", "minLength": 1}, "evidence_refs": IDS,
              "tool": {"type": "object", "additionalProperties": False,
                       "required": ["tool_id", "tool_version", "provider_id", "arguments"],
                       "properties": {"tool_id": {"type": "string"}, "tool_version": {"type": "string"},
                                      "provider_id": {"type": "string"}, "arguments": {"type": "object",
                                        "additionalProperties": False, "required": ["max_entries"],
                                        "properties": {"max_entries": {"const": 64}}}}},
              "assessment": copy.deepcopy(OLLAMA_FORMAT_SCHEMA_V2["properties"]["assessment"]),
              "old_evidence_ids": IDS, "new_evidence_ids": IDS,
              "new_fact_uses": {"type": "array", "maxItems": 3, "items": {
                  "type": "object", "additionalProperties": False,
                  "required": ["evidence_id", "library", "symbol", "why_relevant"],
                  "properties": {k: {"type": "string", "minLength": 1} for k in ("evidence_id", "library", "symbol", "why_relevant")}}},
              "assessment_changed": {"type": "boolean"}, "change_explanation": {"type": "string", "minLength": 1},
              "stop_reason": {"type": "string", "minLength": 1}}}


def parse(raw):
    obj = json.loads(raw)
    try:
        Draft202012Validator(FORMAT).validate(obj)
    except ValidationError as exc:
        raise ValueError("Invalid action schema: " + exc.message) from exc
    if obj["action"] == "TOOL_CALL" and "tool" not in obj:
        raise ValueError("TOOL_CALL requires tool")
    if obj["action"] == "FINISH":
        for key in ("assessment", "old_evidence_ids", "new_evidence_ids", "new_fact_uses", "assessment_changed", "change_explanation", "stop_reason"):
            if key not in obj:
                raise ValueError("FINISH requires " + key)
    return obj


def for_context(ctx):
    """Capability mask only: FINISH remains an option when a tool is available."""
    contract = copy.deepcopy(FORMAT)
    tools = ctx["facts"]["available_tools"]
    if not tools:
        contract["properties"]["action"]["enum"] = ["FINISH", "REQUEST_MORE_EVIDENCE"]
        contract["properties"].pop("tool")
    elif len(tools) == 1:
        for key in ("tool_id", "tool_version", "provider_id"):
            contract["properties"]["tool"]["properties"][key] = {"const": tools[0][key]}
    return contract

orchestrator/core.py:
"""D1 - Orchestrator Core for the D.0 Trusted Tool Orchestrator.

D1 COMPOSES the real modules; it does not reimplement D2-D9. It drives one tool
call through the documented lifecycle (docs/d0/02_CONTRACTS_AND_LIFECYCLE.md):

    PROPOSED -> VALIDATED -> POLICY_EVALUATED
        | DENY            -> note + REJECTED (no execution)
        | REQUIRE_APPROVAL-> WAITING_APPROVAL (no execution here)
        | ALLOW
        v
    ADMITTED -> TARGET_REVALIDATED -> RUNNING (D5/D6)
        -> VALIDATE (D7) -> SIGN (D8) -> COMMIT (D9, revision-aware) -> Node C

Guarantees:
  * Fail-closed: any error/uncertainty yields REJECTED/FAILED, never execution.
  * Idempotency: a durable JSONL run ledger keyed by call_id + canonical payload
    digest. Same call_id + same payload that already reached a terminal state is
    returned without re-executing; same call_id + different payload raises
    IdempotencyConflict. No blind retry of a call that already started.
  * Concurrency: the final COMMIT uses D9's revision-aware compare-and-swap
    (expected_revision under the Node C lock). A stale revision aborts safely
    (CASE_REVISION_STALE) rather than overwriting a newer case; the caller replans.
  * Cancellation/timeout: a threading.Event is threaded down to D5/D6.
  * Durable audit: every terminal run is appended to the run ledger.

Trust: provider/tool output is UNTRUSTED_CONTENT; D1 never interprets it as
instructions. Signing keys come from D8 and are never exposed to tools/Agent.
"""
from __future__ import annotations

import json
import threading
from dataclasses import dataclass, asdict, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Dict, Mapping, Optional

import case_manager as cm
from d0.validate import digest
from orchestrator import registry as d2
from orchestrator.input_validator import validate_tool_call, ValidationError
from orchestrator.policy_engine import PolicyEngine, PolicyError
from orchestrator.provider_install import ProviderInstallError
from orchestrator.result_validator import ResultValidationError
from orchestrator.case_bridge import CaseBridge, StaleRevisionError
from orchestrator.execution_adapter import ember_result_from_execution


class OrchestratorError(Exception):
    """Base error for the D1 orchestrator."""


class IdempotencyConflict(OrchestratorError):
    """Same call_id re-submitted with a different canonical payload."""


# Default per-tool D5->D7 normalizers (extend for new tools; no generic fake builder).
DEFAULT_RESULT_ADAPTERS: Dict[str, Callable] = {
    "static.ember_features": ember_result_from_execution,
}

_TERMINAL = {"SUCCESS", "PARTIAL", "FAILED", "TIMEOUT", "CANCELLED", "DENY", "REJECTED"}


@dataclass
class RunRecord:
    call_id: Optional[str]
    phase: str                      # terminal phase reached
    outcome: str                    # SUCCESS/PARTIAL/FAILED/TIMEOUT/CANCELLED/DENY/REQUIRE_APPROVAL/REJECTED
    reason_code: Optional[str] = None
    run_id: Optional[str] = None
    decision_id: Optional[str] = None
    revision: Optional[int] = None
    payload_digest: Optional[str] = None
    error: Optional[str] = None
    recorded_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def is_terminal(self) -> bool:
        return self.outcome in _TERMINAL


class Orchestrator:
    """Composes D2/D3/D4/D8/D5/D6/D7/D9 to run one tool call end to end."""

    def __init__(self, *, registry, policy: PolicyEngine, signer, installation,
                 bridge: CaseBridge, artifact_root: Path | str, run_ledger_path: Path | str,
                 executor_factory: Optional[Callable] = None,
                 result_adapters: Optional[Mapping[str, Callable]] = None):
        self._registry = registry
        self._policy = policy
        self._signer = signer
        self._installation = installation
        self._bridge = bridge
        self._artifact_root = Path(artifact_root)
        self._ledger_path = Path(run_ledger_path)
        self._result_adapters = dict(result_adapters or DEFAULT_RESULT_ADAPTERS)
        self._lock = threading.Lock()
        if executor_factory is None:
            from orchestrator.executor import ToolExecutor
            executor_factory = lambda root: ToolExecutor(root)
        self._executor_factory = executor_factory

    # -- public API ---------------------------------------------------------
    def run_tool_call(self, call: Mapping[str, Any], case_path: Path | str, *,
                      cancel: Optional[threading.Event] = None,
                      input_schemas: Optional[Mapping[str, Any]] = None) -> RunRecord:
        call = dict(call)
        case_path = Path(case_path)
        call_id = call.get("call_id")
        payload_digest = digest(call)

        # 1. PROPOSED - idempotency against the durable run ledger.
        prior = self._lookup(call_id, payload_digest)
        if prior is not None:
            return prior

        record = self._run(call, case_path, call_id, payload_digest, cancel, input_schemas)
        self._append(record)
        return record

    # -- lifecycle ----------------------------------------------------------
    def _run(self, call, case_path, call_id, payload_digest, cancel, input_schemas) -> RunRecord:
        def rejected(phase, code, error=None, **kw):
            return RunRecord(call_id=call_id, phase=phase, outcome="REJECTED",
                             reason_code=code, payload_digest=payload_digest, error=error, **kw)

        # 2. Read the case snapshot from Node C.
        try:
            state = cm.validate_case(cm.read_json(case_path))
            snapshot = {"case_id": state["case_id"], "revision": state.get("revision", 1),
                        "target_ref": state["target_ref"]}
        except Exception as exc:
            return rejected("PROPOSED", "INTERNAL_ERROR", f"Case unreadable: {exc}")

        # 3. VALIDATED - D2 lookup + D3 validation.
        try:
            spec = self._registry.get_tool(call["tool_id"], call.get("tool_version"),
                                           require_enabled=True)
        except d2.ToolDisabledError as exc:
            return rejected("VALIDATED", "TOOL_DISABLED", str(exc))
        except d2.ToolUnknownError as exc:
            return rejected("VALIDATED", "TOOL_UNKNOWN", str(exc))
        except d2.RegistryError as exc:
            return rejected("VALIDATED", "INTERNAL_ERROR", str(exc))
        provider_available = self._registry.is_provider_available(spec["provider"]["id"])
        try:
            validate_tool_call(call, spec, snapshot, input_schemas=input_schemas,
                               provider_available=provider_available)
        except ValidationError as exc:
            return rejected("VALIDATED", exc.code, exc.message)

        # 4. POLICY_EVALUATED - D4.
        try:
            decision = self._policy.evaluate(call, spec, snapshot)
        except PolicyError as exc:
            return rejected("POLICY_EVALUATED", "POLICY_DENIED", str(exc))
        decision_id = decision["decision_id"]
        if decision["outcome"] == "DENY":
            self._note_denied(case_path, call, decision)
            return RunRecord(call_id=call_id, phase="POLICY_EVALUATED", outcome="DENY",
                             reason_code=decision["reason_code"], decision_id=decision_id,
                             revision=snapshot["revision"], payload_digest=payload_digest)
        if decision["outcome"] == "REQUIRE_APPROVAL":
            # Tool-call approval gate: not admitted here. No execution. An authenticated
            # analyst step (out-of-band) must re-submit; D.0 defines no tool-call
            # approval wire schema, so we fail closed to WAITING_APPROVAL.
            return RunRecord(call_id=call_id, phase="WAITING_APPROVAL", outcome="REQUIRE_APPROVAL",
                             reason_code=decision["reason_code"], decision_id=decision_id,
                             revision=snapshot["revision"], payload_digest=payload_digest)

        # 5. ADMITTED -> TARGET_REVALIDATED -> RUNNING (D5/D6).
        try:
            adapter = self._installation.pinned_adapter_for(spec)
        except ProviderInstallError as exc:
            return rejected("ADMITTED", "PROVIDER_UNAVAILABLE", str(exc), decision_id=decision_id)
        executor = self._executor_factory(self._artifact_root)
        try:
            output = executor.execute(call, spec, decision, snapshot, adapter, cancel=cancel)
        except Exception as exc:
            code = getattr(exc, "code", "INTERNAL_ERROR")
            return rejected("RUNNING", code, str(exc), decision_id=decision_id)

        # 6. VALIDATE (D7) via the per-tool normalizer.
        normalizer = self._result_adapters.get(call["tool_id"])
        if normalizer is None:
            return rejected("VALIDATE", "RESULT_INVALID",
                            f"No D7 normalizer registered for {call['tool_id']}",
                            run_id=output.receipt.get("run_id"), decision_id=decision_id)
        try:
            tool_result = normalizer(output, call, spec, artifact_root=executor.root)
        except ResultValidationError as exc:
            return rejected("VALIDATE", exc.code, exc.message,
                            run_id=output.receipt.get("run_id"), decision_id=decision_id)

        # 7. SIGN (D8) + 8. COMMIT (D9, revision-aware).
        try:
            commit = self._bridge.commit_tool_result(
                case_path, tool_result, output.receipt,
                trusted_key=self._signer.tool_key(),
                expected_revision=snapshot["revision"])
        except StaleRevisionError as exc:
            # Concurrent writer changed the case; caller must replan (no overwrite).
            return rejected("COMMIT", "CASE_REVISION_STALE", str(exc),
                            run_id=output.receipt.get("run_id"), decision_id=decision_id)
        except Exception as exc:
            return rejected("COMMIT", "INTERNAL_ERROR", str(exc),
                            run_id=output.receipt.get("run_id"), decision_id=decision_id)

        return RunRecord(
            call_id=call_id, phase="COMMITTED", outcome=tool_result["status"],
            reason_code=None, run_id=output.receipt.get("run_id"), decision_id=decision_id,
            revision=commit["revision"], payload_digest=payload_digest,
            error=(tool_result.get("error") or {}).get("code") if tool_result.get("error") else None)

    # -- helpers ------------------------------------------------------------
    def _note_denied(self, case_path, call, decision) -> None:
        """Record a policy denial as a Node C NOTE (never as a tool success)."""
        try:
            cm.apply_update(case_path, "action", {
                "event_id": f"NOTE-POLICY-DENY-{decision['decision_id'][:28]}",
                "action": "NOTE", "actor": "D4_POLICY_ENGINE",
                "reason": f"Tool call {call.get('call_id')} DENIED: {decision['reason_code']}"})
        except Exception:
            # Denial record is best-effort; the run ledger still captures the DENY.
            pass

    def _lookup(self, call_id, payload_digest) -> Optional[RunRecord]:
        if not self._ledger_path.exists() or call_id is None:
            return None
        with self._lock:
            for raw in self._ledger_path.read_text(encoding="utf-8").splitlines():
                raw = raw.strip()
                if not raw:
                    continue
                rec = json.loads(raw)
                if rec.get("call_id") == call_id:
                    if rec.get("payload_digest") == payload_digest:
                        return RunRecord(**rec)
                    raise IdempotencyConflict(
                        f"call_id {call_id} re-submitted with a different payload")
        return None

    def _append(self, record: RunRecord) -> None:
        if not record.is_terminal():
            return
        with self._lock:
            self._ledger_path.parent.mkdir(parents=True, exist_ok=True)
            with open(self._ledger_path, "a", encoding="utf-8") as f:
                f.write(json.dumps(asdict(record), ensure_ascii=False, sort_keys=True) + "\n")
                f.flush()

orchestrator/execution_control.py:
"""D6: bounded trusted-adapter execution on Windows, with Job Object ownership.

This is NOT a malware sandbox. The gated worker runs only trusted adapter argv.
It waits for admission into the job before creating any adapter descendants.
All provider output remains untrusted bytes for D7; no parsing into observations.
"""
from __future__ import annotations

import ctypes
from ctypes import wintypes as w
from dataclasses import dataclass
import json
import hashlib
import os
from pathlib import Path
import subprocess
import sys
import threading
import time


@dataclass(frozen=True)
class ControlResult:
    outcome: str
    error_code: str | None
    exit_code: int | None
    output_bytes: int
    duration_ms: int
    cleanup_status: str
    remaining_owned_resources: tuple[str, ...]
    stream_sha256: tuple[tuple[str, str], ...] = ()


class WindowsJob:
    """Unnamed, non-inheritable job; no breakaway permission is granted."""

    def __init__(self):
        if os.name != 'nt':
            raise OSError('Windows Job Objects required; no weaker fallback')
        self.api = ctypes.WinDLL('kernel32', use_last_error=True)
        signatures = {
            'CreateJobObjectW': ([ctypes.c_void_p, w.LPCWSTR], w.HANDLE),
            'SetInformationJobObject': ([w.HANDLE, ctypes.c_int, ctypes.c_void_p, w.DWORD], w.BOOL),
            'AssignProcessToJobObject': ([w.HANDLE, w.HANDLE], w.BOOL),
            'TerminateJobObject': ([w.HANDLE, w.UINT], w.BOOL),
            'QueryInformationJobObject': ([w.HANDLE, ctypes.c_int, ctypes.c_void_p, w.DWORD, ctypes.c_void_p], w.BOOL),
            'CloseHandle': ([w.HANDLE], w.BOOL),
        }
        for name, (args, result) in signatures.items():
            function = getattr(self.api, name)
            function.argtypes, function.restype = args, result

        class BasicLimits(ctypes.Structure):
            _fields_ = [('process_time', ctypes.c_longlong), ('job_time', ctypes.c_longlong),
                        ('flags', w.DWORD), ('min_ws', ctypes.c_size_t),
                        ('max_ws', ctypes.c_size_t), ('active_limit', w.DWORD),
                        ('affinity', ctypes.c_size_t), ('priority', w.DWORD), ('scheduling', w.DWORD)]

        class IO(ctypes.Structure):
            _fields_ = [(name, ctypes.c_ulonglong) for name in
                        ('read_ops', 'write_ops', 'other_ops', 'read_bytes', 'write_bytes', 'other_bytes')]

        class ExtendedLimits(ctypes.Structure):
            _fields_ = [('basic', BasicLimits), ('io', IO), ('process_memory', ctypes.c_size_t),
                        ('job_memory', ctypes.c_size_t), ('peak_process', ctypes.c_size_t),
                        ('peak_job', ctypes.c_size_t)]

        self.handle = self.api.CreateJobObjectW(None, None)
        if not self.handle:
            raise ctypes.WinError(ctypes.get_last_error())
        limits = ExtendedLimits()
        limits.basic.flags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
        if not self.api.SetInformationJobObject(self.handle, 9, ctypes.byref(limits), ctypes.sizeof(limits)):
            error = ctypes.WinError(ctypes.get_last_error())
            self.close()
            raise error

    def assign(self, process):
        if not self.api.AssignProcessToJobObject(self.handle, int(process._handle)):
            raise ctypes.WinError(ctypes.get_last_error())

    def active_count(self):
        class Accounting(ctypes.Structure):
            _fields_ = [('user', ctypes.c_longlong), ('kernel', ctypes.c_longlong),
                        ('period_user', ctypes.c_longlong), ('period_kernel', ctypes.c_longlong),
                        ('faults', w.DWORD), ('total', w.DWORD), ('active', w.DWORD), ('terminated', w.DWORD)]
        info = Accounting()
        if not self.api.QueryInformationJobObject(self.handle, 1, ctypes.byref(info), ctypes.sizeof(info), None):
            raise ctypes.WinError(ctypes.get_last_error())
        return info.active

    def cleanup(self, grace_seconds=3.0):
        # Terminate even on normal parent exit: descendants may still be running.
        if self.active_count() and not self.api.TerminateJobObject(self.handle, 1):
            raise ctypes.WinError(ctypes.get_last_error())
        end = time.monotonic() + grace_seconds
        while self.active_count():
            if time.monotonic() >= end:
                return False
            time.sleep(0.01)
        return True

    def close(self):
        if self.handle:
            self.api.CloseHandle(self.handle)
            self.handle = None


def clean_environment(workdir: Path):
    """Do not pass parent tokens, PYTHONPATH, PATH or signing secrets to adapters."""
    env = {k: os.environ[k] for k in ('SystemRoot', 'WINDIR') if k in os.environ}
    env.update(TEMP=str(workdir), TMP=str(workdir), PYTHONIOENCODING='utf-8')
    return env


class ExecutionControl:
    """One controlled run. Caller supplies absolute trusted argv and private cwd.

    Captured stdout+stderr share one cap (also limited by artifact budget).
    Direct adapter filesystem writes are not sandboxed; only trusted read-only
    adapters belong here. A VM backend must implement its own isolation gate.
    """

    def run(self, argv: list[str], workdir: Path, *, timeout_ms: int,
            max_output_bytes: int, max_artifact_bytes: int,
            cancel: threading.Event | None = None) -> ControlResult:
        if any(type(n) is not int or n <= 0 for n in (timeout_ms, max_output_bytes, max_artifact_bytes)):
            raise ValueError('Positive integer limits required')
        if not argv or not Path(argv[0]).is_absolute():
            raise ValueError('Absolute trusted executable required')
        if os.name != 'nt':
            raise OSError('Windows-only execution backend')
        workdir = Path(workdir)
        cap = min(max_output_bytes, max_artifact_bytes)
        started = time.monotonic()
        cancel = cancel if cancel is not None else threading.Event()
        outcome, error, exit_code = 'FAILED', None, None
        count = 0
        lock = threading.Lock()
        overflow, reader_error = threading.Event(), threading.Event()
        process, job = None, None
        readers = []
        remaining = []
        stream_hashes = {}
        cleanup = 'NOT_REQUIRED'

        def drain(pipe, path):
            nonlocal count
            checksum = hashlib.sha256()
            try:
                with path.open('xb', buffering=0) as output:
                    while block := pipe.read(4096):
                        with lock:
                            keep = block[:max(0, cap - count)]
                            output.write(keep)
                            checksum.update(keep)
                            count += len(keep)
                            if len(keep) != len(block):
                                overflow.set()
            except OSError:
                reader_error.set()
            finally:
                with lock:
                    stream_hashes[path.name] = checksum.hexdigest()
                pipe.close()

        try:
            if cancel.is_set():
                return ControlResult('CANCELLED', 'CANCELLED', None, 0, 0, 'NOT_REQUIRED', ())
            job = WindowsJob()
            # Use the real interpreter, not a venv launcher that could fork before assignment.
            worker_python = getattr(sys, '_base_executable', sys.executable)
            process = subprocess.Popen(
                [worker_python, '-I', str(Path(__file__).resolve()), '--gated-worker'],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                cwd=workdir, env=clean_environment(workdir), shell=False, close_fds=True,
                creationflags=subprocess.CREATE_NO_WINDOW, bufsize=0)
            job.assign(process)
            for name, pipe in [('stdout.bin', process.stdout), ('stderr.bin', process.stderr)]:
                thread = threading.Thread(target=drain, args=(pipe, workdir / name), daemon=True)
                thread.start()
                readers.append(thread)
            payload = json.dumps(argv, ensure_ascii=True).encode('ascii')
            if len(payload) > 24000:
                raise ValueError('Adapter argv exceeds control-message limit')
            process.stdin.write(payload)
            process.stdin.close()  # Release the worker ONLY after successful job assignment.
            while True:
                if cancel.is_set():
                    outcome, error = 'CANCELLED', 'CANCELLED'
                    break
                if overflow.is_set():
                    outcome, error = 'FAILED', 'BUDGET_EXCEEDED'
                    break
                if reader_error.is_set():
                    outcome, error = 'FAILED', 'INTERNAL_ERROR'
                    break
                exit_code = process.poll()
                if exit_code is not None:
                    outcome = 'SUCCESS' if exit_code == 0 else 'FAILED'
                    error = None if exit_code == 0 else 'PROVIDER_FAILED'
                    break
                if (time.monotonic() - started) * 1000 >= timeout_ms:
                    outcome, error = 'TIMEOUT', 'TIMEOUT'
                    break
                time.sleep(0.01)
        except (OSError, ValueError):
            outcome, error = 'FAILED', 'PROVIDER_UNAVAILABLE'
        except BaseException:
            # Cleanup must happen for KeyboardInterrupt and other caller interruptions too.
            outcome, error = 'CANCELLED', 'CANCELLED'
            raise
        finally:
            if process is not None:
                cleanup = 'COMPLETE'
                try:
                    if job is not None and not job.cleanup():
                        remaining.append('job_processes')
                except OSError:
                    remaining.append('job_cleanup_unverified')
                if job is not None:
                    job.close()
                    job = None
                try:
                    if process.poll() is None:
                        process.kill()  # Also handles assignment failure; gate was never released.
                    process.wait(timeout=3)
                except (OSError, subprocess.TimeoutExpired):
                    remaining.append('worker_process')
                for thread in readers:
                    thread.join(timeout=3)
                    if thread.is_alive():
                        remaining.append('output_reader')
                for pipe in (process.stdin, process.stdout, process.stderr):
                    if pipe and not pipe.closed and 'output_reader' not in remaining:
                        pipe.close()
                if remaining:
                    cleanup = 'INCOMPLETE'
            if job is not None:
                job.close()
        if overflow.is_set() and outcome not in ('CANCELLED', 'TIMEOUT'):
            outcome, error = 'FAILED', 'BUDGET_EXCEEDED'
        if reader_error.is_set():
            outcome, error = 'FAILED', 'INTERNAL_ERROR'
        if cleanup == 'INCOMPLETE' and outcome == 'SUCCESS':
            outcome, error = 'FAILED', 'CLEANUP_INCOMPLETE'
        return ControlResult(outcome, error, exit_code, count,
                             round((time.monotonic() - started) * 1000), cleanup, tuple(remaining),
                             tuple(sorted(stream_hashes.items())))


class VMResetGate:
    """Interface state only, NOT a VM adapter or evidence of real isolation.

    A failed reset blocks reuse until the trusted owner verifies a new reset.
    No host fallback exists; booleans are trusted-backend inputs, not proof.
    """
    def __init__(self):
        self._ready = False

    @property
    def ready(self):
        return self._ready

    def begin(self, *, isolation_verified: bool, snapshot_verified: bool):
        if not self._ready or not isolation_verified or not snapshot_verified:
            raise RuntimeError('VM unavailable or reset/isolation not verified')
        self._ready = False

    def record_reset(self, *, verified: bool):
        self._ready = verified is True


def _gated_worker():
    # Trusted bootstrap: no descendants or provider imports before parent closes stdin.
    payload = sys.stdin.buffer.read(24001)
    if not payload or len(payload) > 24000:
        return 125
    argv = json.loads(payload)
    if not isinstance(argv, list) or not argv or not all(isinstance(s, str) for s in argv):
        return 125
    try:
        return subprocess.call(argv, stdin=subprocess.DEVNULL, shell=False, close_fds=True)
    except OSError:
        return 126


if __name__ == '__main__':
    if sys.argv[1:] != ['--gated-worker']:
        raise SystemExit('Internal worker only')
    raise SystemExit(_gated_worker())

orchestrator/executor.py:
"""D5: trusted-backend-only, read-only FILE adapter executor (d0-v1).

No public CLI accepts ALLOW from an Agent. D1 owns authenticated/atomic admission,
D2 owns installed provider configuration, D7 normalizes bytes, D8 signs, D9 commits.
This API checks supplied snapshots but cannot implement those trust boundaries.
"""
from __future__ import annotations

from contextlib import ExitStack, contextmanager
import copy
import ctypes
from ctypes import wintypes
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import stat
import threading
import time
import uuid

from d0.validate import ContractError, canonical_json_bytes, digest, validate, verify_tool_call
from .execution_control import ExecutionControl


class ExecutionRejected(ValueError):
    """Pre-execution rejection; codes are internal, not ToolResult.error.code."""
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code


@dataclass(frozen=True)
class PinnedAdapter:
    """Installed by trusted D2/backend, NEVER constructed from ToolCall arguments.

    command is fixed executable + adapter prefix, pins are (absolute path, sha256).
    All code-bearing files must be pinned by the installer. Adapter protocol is:
    <command> --target <locked-staged-file> --arguments-json <canonical-object>.
    """
    provider_id: str
    version: str
    adapter_id: str
    command: tuple[str, ...]
    pins: tuple[tuple[str, str], ...]

    def provider(self):
        return {'id': self.provider_id, 'version': self.version,
                'adapter': self.adapter_id, 'runtime': 'subprocess'}


@dataclass(frozen=True)
class ExecutionOutput:
    receipt: dict
    raw_artifacts: tuple[dict, ...]
    error: dict | None
    exit_code: int | None
    run_directory: Path


def now():
    return datetime.now(timezone.utc).isoformat()


def checked_path(value):
    """Reject relative/device/UNC/ADS paths and existing reparse components.

    Artifact/provider directories must additionally be owned/protected by the
    trusted backend. This check does not create Windows ACL isolation.
    """
    path = Path(value)
    if not path.is_absolute() or str(path).startswith(('\\\\', '//')):
        raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'Local absolute path required')
    if '..' in path.parts or any(':' in part for part in path.parts[1:]):
        raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'Traversal or alternate stream rejected')
    for part in reversed([path, *path.parents]):
        info = part.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
            raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'Reparse points are not supported')
    return path


@contextmanager
def locked_reader(path):
    """Hold Windows read access WITHOUT write/delete sharing until exit."""
    if os.name != 'nt':
        raise ExecutionRejected('PROVIDER_UNAVAILABLE', 'Windows-only locked-file backend')
    import msvcrt
    path = checked_path(path)
    api = ctypes.WinDLL('kernel32', use_last_error=True)
    api.CreateFileW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD,
                               ctypes.c_void_p, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    api.CreateFileW.restype = wintypes.HANDLE
    api.CloseHandle.argtypes, api.CloseHandle.restype = [wintypes.HANDLE], wintypes.BOOL
    handle = api.CreateFileW(str(path), 0x80000000, 1, None, 3, 0x00200000, None)
    if handle == ctypes.c_void_p(-1).value:
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        fd = msvcrt.open_osfhandle(handle, os.O_RDONLY | os.O_BINARY)
    except BaseException:
        api.CloseHandle(handle)
        raise
    with os.fdopen(fd, 'rb') as stream:
        opened = os.fstat(stream.fileno())
        current = path.lstat()
        if (not stat.S_ISREG(opened.st_mode) or getattr(current, 'st_file_attributes', 0) & 0x400
                or (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino)):
            raise ExecutionRejected('TARGET_CHANGED', 'Opened file does not match path identity')
        yield stream


def check_deadline(deadline, cancel):
    if cancel is not None and cancel.is_set():
        raise ExecutionRejected('CANCELLED', 'Cancelled before adapter dispatch')
    if time.monotonic() >= deadline:
        raise ExecutionRejected('TIMEOUT', 'Preparation exceeded the run deadline')


def stream_digest(stream, deadline, cancel, destination=None):
    stream.seek(0)
    checksum = hashlib.sha256()
    while True:
        check_deadline(deadline, cancel)
        block = stream.read(1024 * 1024)
        if not block:
            break
        checksum.update(block)
        if destination is not None:
            destination.write(block)
    return checksum.hexdigest()


class ToolExecutor:
    """Single-flight per instance; D1/D2 enforce cross-instance/global concurrency.

    Only trusted, read-only subprocess adapters on FILE targets are supported.
    All foreign-code, mutation, approval-required and PROCESS calls fail closed.
    """
    def __init__(self, artifact_root: Path, *, control: ExecutionControl | None = None):
        self.root = Path(artifact_root)
        self.root.mkdir(exist_ok=True)
        checked_path(self.root)
        self.control = control if control is not None else ExecutionControl()
        self._slot = threading.Lock()
        self._quarantined = False

    def execute(self, call: dict, spec: dict, policy: dict, case_snapshot: dict,
                adapter: PinnedAdapter, *, cancel: threading.Event | None = None) -> ExecutionOutput:
        if not self._slot.acquire(blocking=False):
            raise ExecutionRejected('BUDGET_EXCEEDED', 'Executor already owns an active run')
        try:
            if self._quarantined:
                raise ExecutionRejected('CLEANUP_INCOMPLETE', 'Executor quarantined after incomplete cleanup')
            return self._execute(copy.deepcopy(call), copy.deepcopy(spec), copy.deepcopy(policy),
                                 copy.deepcopy(case_snapshot), adapter, cancel)
        finally:
            self._slot.release()

    def _execute(self, call, spec, policy, case, adapter, cancel):
        try:
            validate('tool_call', call)
            validate('tool_spec', spec)
            validate('policy_decision', policy)
            validate('target_ref', call['target_ref'])
        except (ContractError, KeyError, TypeError, ValueError) as exc:
            raise ExecutionRejected('SCHEMA_INVALID', 'Invalid D.0 input') from exc
        if call['case_id'] != case.get('case_id') or call['expected_revision'] != case.get('revision'):
            raise ExecutionRejected('CASE_REVISION_STALE', 'Case snapshot mismatch; D1 must re-admit')
        if any(policy[k] != call[k] for k in ('call_id', 'case_id', 'expected_revision')):
            raise ExecutionRejected('POLICY_DENIED', 'Policy is bound to a different call/case revision')
        if policy['outcome'] != 'ALLOW':
            code = 'APPROVAL_REQUIRED' if policy['outcome'] == 'REQUIRE_APPROVAL' else 'POLICY_DENIED'
            raise ExecutionRejected(code, 'No admitted execution')
        effects = spec['effects']
        if any(effects[k] for k in ('executes_foreign_code', 'mutates_target', 'writes_filesystem', 'requires_human_approval')):
            raise ExecutionRejected('POLICY_DENIED', 'Only read-only host analysis supported; VM/approval backend absent')
        if spec['provider'] != adapter.provider() or call['provider_id'] != adapter.provider_id:
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Exact installed provider binding required')
        if not spec['enabled']:
            raise ExecutionRejected('TOOL_DISABLED', 'Installed tool is disabled')
        if (call['tool_id'], call['tool_version']) != (spec['tool_id'], spec['tool_version']):
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Tool identity/version mismatch')
        if call['target_ref']['kind'] != 'FILE':
            raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'PROCESS adapter not implemented')
        try:
            verify_tool_call(spec, call, case)
        except (ContractError, ValueError, KeyError) as exc:
            raise ExecutionRejected('SCHEMA_INVALID', 'Tool/case/target/limit validation failed') from exc
        ref = call['target_ref']
        if not ref['verified_digest']:
            raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'Verified SHA-256 required for FILE execution')
        limits = {k: min(spec['limits'][k], policy['effective_limits'][k]) for k in spec['limits']}
        for key in call['budget']:
            limits[key] = min(limits[key], call['budget'][key])
        started_at, started = now(), time.monotonic()
        deadline = started + limits['timeout_ms'] / 1000
        check_deadline(deadline, cancel)
        if not adapter.command or not Path(adapter.command[0]).is_absolute():
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Absolute installed command required')
        if Path(adapter.command[0]).suffix.lower() != '.exe':
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Native EXE required; batch/shell launchers unsupported')
        pins = dict(adapter.pins)
        if adapter.command[0] not in pins or not pins:
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Provider executable must be pinned')
        # Absolute code arguments (e.g. Python script) also require declared pins.
        if any(Path(arg).is_absolute() and arg not in pins for arg in adapter.command):
            raise ExecutionRejected('PROVIDER_MISMATCH', 'Unpinned provider code path')
        run_id = 'RUN-' + uuid.uuid4().hex
        run_dir = self.root / run_id
        staged = run_dir / 'target.bin'
        binding = None
        control_result = None
        try:
            with ExitStack() as stack:
                for path, expected in adapter.pins:
                    try:
                        provider_stream = stack.enter_context(locked_reader(path))
                    except OSError as exc:
                        raise ExecutionRejected('PROVIDER_UNAVAILABLE', 'Pinned provider cannot be opened') from exc
                    if stream_digest(provider_stream, deadline, cancel) != expected:
                        raise ExecutionRejected('PROVIDER_MISMATCH', 'Installed provider digest changed')
                source = stack.enter_context(locked_reader(ref['observed']['path']))
                info = os.fstat(source.fileno())
                observed = {'device': info.st_dev, 'inode': info.st_ino,
                            'size_bytes': info.st_size, 'mtime_ns': info.st_mtime_ns}
                if any(value is not None and observed.get(k) != value
                       for k, value in ref['snapshot'].items() if k in observed):
                    raise ExecutionRejected('TARGET_CHANGED', 'Opened file differs from collected snapshot')
                checked_path(self.root)
                run_dir.mkdir(exist_ok=False)
                with staged.open('xb') as destination:
                    actual = stream_digest(source, deadline, cancel, destination)
                if actual != ref['verified_digest']['value']:
                    raise ExecutionRejected('TARGET_CHANGED', 'Opened file hash differs from admitted target')
                staged_reader = stack.enter_context(locked_reader(staged))
                if stream_digest(staged_reader, deadline, cancel) != actual:
                    raise ExecutionRejected('ARTIFACT_INTEGRITY_FAILED', 'Staged bytes failed verification')
                binding = {'status': 'VERIFIED', 'method': 'windows_locked_handle_and_locked_staged_sha256',
                           'observed_ref': copy.deepcopy(ref), 'verified_at': now()}
                arguments = canonical_json_bytes(call['arguments']).decode('utf-8')
                argv = [*adapter.command, '--target', str(staged), '--arguments-json', arguments]
                if len(json.dumps(argv, ensure_ascii=True).encode('ascii')) > 24000:
                    raise ExecutionRejected('BUDGET_EXCEEDED', 'Arguments exceed adapter control-message budget')
                check_deadline(deadline, cancel)
                control_result = self.control.run(argv, run_dir,
                    timeout_ms=max(1, int((deadline - time.monotonic()) * 1000)),
                    max_output_bytes=limits['max_output_bytes'],
                    max_artifact_bytes=limits['max_artifact_bytes'], cancel=cancel)
        except OSError as exc:
            raise ExecutionRejected('TARGET_IDENTITY_UNAVAILABLE', 'File/provider access unavailable; no unsafe fallback') from exc
        finally:
            # Never remove arbitrary directories. Only the exact generated staging file.
            if staged.exists() and (control_result is None or control_result.cleanup_status != 'INCOMPLETE'):
                try:
                    staged.unlink()
                except OSError:
                    self._quarantined = True
            if control_result is not None and control_result.cleanup_status == 'INCOMPLETE':
                self._quarantined = True
        remaining = list(control_result.remaining_owned_resources)
        if staged.exists():
            remaining.append('staged_target')
            self._quarantined = True
        cleanup = 'INCOMPLETE' if remaining else control_result.cleanup_status
        outcome = control_result.outcome
        error_code = control_result.error_code
        if cleanup == 'INCOMPLETE' and outcome == 'SUCCESS':
            outcome, error_code = 'FAILED', 'CLEANUP_INCOMPLETE'
        receipt = {'schema_version': 'd0-v1', 'run_id': run_id, 'call_id': call['call_id'],
                   'case_id': call['case_id'], 'tool_id': call['tool_id'], 'tool_version': call['tool_version'],
                   'provider': adapter.provider(), 'arguments_sha256': digest(call['arguments']),
                   'target_binding': binding, 'started_at': started_at, 'finished_at': now(),
                   'outcome': outcome, 'cleanup': {'status': cleanup, 'remaining_owned_resources': remaining},
                   'resources': {'duration_ms': round((time.monotonic() - started) * 1000),
                                 'output_bytes': control_result.output_bytes}}
        validate('execution_receipt', receipt)
        artifacts = []
        artifact_size = 0
        for name in ('stdout.bin', 'stderr.bin'):
            path = run_dir / name
            if path.exists():
                with locked_reader(path) as stream:
                    size = os.fstat(stream.fileno()).st_size
                    artifact_size += size
                    if artifact_size > min(limits['max_output_bytes'], limits['max_artifact_bytes']):
                        receipt['outcome'], error_code = 'FAILED', 'ARTIFACT_INTEGRITY_FAILED'
                        continue  # Never hash an unexpectedly oversized provider-created artifact.
                    checksum = hashlib.sha256()
                    while chunk := stream.read(1024 * 1024):
                        checksum.update(chunk)
                if checksum.hexdigest() != dict(control_result.stream_sha256).get(name):
                    receipt['outcome'], error_code = 'FAILED', 'ARTIFACT_INTEGRITY_FAILED'
                artifacts.append({'artifact_id': 'ART-' + uuid.uuid4().hex,
                                  'sha256': checksum.hexdigest(), 'size_bytes': size,
                                  'media_type': 'application/octet-stream',
                                  'relative_path': f'{run_id}/{name}'})
        if artifact_size != control_result.output_bytes:
            receipt['outcome'], error_code = 'FAILED', 'ARTIFACT_INTEGRITY_FAILED'
        for artifact in artifacts:
            validate('artifact', artifact)
        error = None if error_code is None else {'code': error_code, 'message': {
            'TIMEOUT': 'Adapter deadline exceeded', 'CANCELLED': 'Cancellation requested',
            'BUDGET_EXCEEDED': 'Combined stdout/stderr artifact cap exceeded',
            'CLEANUP_INCOMPLETE': 'Owned resources remain; executor quarantined',
            'PROVIDER_FAILED': 'Adapter exited with a nonzero status',
            'ARTIFACT_INTEGRITY_FAILED': 'Captured artifact size or digest disagrees with the execution record',
        }.get(error_code, 'Adapter execution unavailable or failed')}
        (run_dir / 'execution_receipt.json').write_bytes(canonical_json_bytes(receipt))
        return ExecutionOutput(receipt, tuple(artifacts), error, control_result.exit_code, run_dir)

orchestrator/provider_install.py:
"""Trusted provider installation binding (D2 Registry -> D5 Executor).

The D2 ToolRegistry (``orchestrator.registry``) stores a ToolSpec whose
``provider`` block names ``id``/``version``/``adapter``/``runtime`` but carries
NO executable path and NO code pins. The D5 executor
(``orchestrator.executor.ToolExecutor.execute``) instead requires a
``PinnedAdapter`` with the absolute command and its SHA-256 pins. This module is
the minimal trusted binding that closes that gap.

SECURITY — the installation data (command + pins) comes ONLY from a trusted
backend configuration supplied out-of-band by the operator/installer. It is
NEVER derived from a ToolCall, from ToolSpec fields, from Agent input or from
any provider payload. ``pinned_adapter_for`` only *looks up* an installation by
the ToolSpec's provider identity; it cannot inject a path. No execution, no
network IO, no filesystem IO happens here. This is control-plane wiring that
would normally be owned by D1/the backend installer, not by D2/D5 themselves.

This module imports the Windows-only D5 submodule (``orchestrator.executor``)
because the ``PinnedAdapter`` type lives with the executor it feeds; it is used
only on the Windows execution path.
"""
from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Mapping, Sequence, Tuple

from orchestrator.executor import PinnedAdapter


class ProviderInstallError(Exception):
    """Base error for provider installation binding."""


class ProviderNotInstalledError(ProviderInstallError):
    """Raised when no trusted installation matches a ToolSpec provider."""


class ProviderBindingMismatchError(ProviderInstallError):
    """Raised when the ToolSpec provider block disagrees with the installation."""


class InvalidInstallationError(ProviderInstallError):
    """Raised when a trusted-config entry is structurally invalid."""


def _check_pin(path: str, sha: str) -> Tuple[str, str]:
    p = Path(path)
    if not isinstance(path, str) or not p.is_absolute() or str(p).startswith(("\\\\", "//")):
        raise InvalidInstallationError("Pinned path must be a local absolute path")
    if ".." in p.parts or any(":" in part for part in p.parts[1:]):
        raise InvalidInstallationError("Pinned path contains traversal or alternate stream")
    if not isinstance(sha, str) or len(sha) != 64 or any(c not in "0123456789abcdef" for c in sha.lower()):
        raise InvalidInstallationError("Pin SHA-256 must be 64 lowercase hex chars")
    return (str(p), sha.lower())


class ProviderInstallation:
    """Registry of trusted provider installations, keyed by provider identity.

    Keyed by ``(provider_id, version, adapter_id)`` — the same tuple a D2
    ToolSpec pins via ADR-005. Only the operator/installer populates it.
    """

    def __init__(self) -> None:
        self._installed: Dict[Tuple[str, str, str], PinnedAdapter] = {}

    def install(self, *, provider_id: str, version: str, adapter_id: str,
                command: Sequence[str], pins: Sequence[Sequence[str]],
                runtime: str = "subprocess") -> PinnedAdapter:
        """Install one trusted provider binding from backend configuration.

        command: fixed executable + adapter prefix (absolute paths for code).
        pins: iterable of (absolute_path, sha256_hex) covering every code-bearing
              file, including command[0].
        """
        if runtime != "subprocess":
            raise InvalidInstallationError("Only the subprocess runtime is supported by D5")
        if not command or not all(isinstance(part, str) and part for part in command):
            raise InvalidInstallationError("command must be a non-empty tuple of strings")
        exe = Path(command[0])
        if not exe.is_absolute():
            raise InvalidInstallationError("command[0] must be an absolute executable path")
        if exe.suffix.lower() != ".exe":
            raise InvalidInstallationError("command[0] must be a native .exe (no batch/shell launcher)")
        checked_pins = tuple(_check_pin(path, sha) for path, sha in pins)
        pin_paths = {path for path, _ in checked_pins}
        if command[0] not in pin_paths:
            raise InvalidInstallationError("command[0] must be pinned")
        # Every absolute code argument must also be pinned (mirrors executor policy).
        for arg in command:
            if Path(arg).is_absolute() and arg not in pin_paths:
                raise InvalidInstallationError(f"Unpinned absolute command argument: {arg}")
        if not all(isinstance(x, str) and x for x in (provider_id, version, adapter_id)):
            raise InvalidInstallationError("provider_id/version/adapter_id must be non-empty strings")
        adapter = PinnedAdapter(
            provider_id=provider_id, version=version, adapter_id=adapter_id,
            command=tuple(command), pins=checked_pins,
        )
        self._installed[(provider_id, version, adapter_id)] = adapter
        return adapter

    @classmethod
    def from_config(cls, config: Mapping[str, Any]) -> "ProviderInstallation":
        """Build from a trusted config dict: {'providers': [ {...}, ... ]}.

        The caller must have loaded this from a trusted source (operator-owned
        file / secret store), never from Agent/ToolCall/provider output.
        """
        if not isinstance(config, Mapping) or not isinstance(config.get("providers"), list):
            raise InvalidInstallationError("config must be a mapping with a 'providers' list")
        inst = cls()
        for entry in config["providers"]:
            if not isinstance(entry, Mapping):
                raise InvalidInstallationError("Each provider entry must be a mapping")
            inst.install(
                provider_id=entry.get("provider_id"),
                version=entry.get("version"),
                adapter_id=entry.get("adapter_id"),
                command=entry.get("command", ()),
                pins=entry.get("pins", ()),
                runtime=entry.get("runtime", "subprocess"),
            )
        return inst

    def pinned_adapter_for(self, spec: Mapping[str, Any]) -> PinnedAdapter:
        """Return the installed PinnedAdapter bound to this ToolSpec's provider.

        Looks up strictly by the ToolSpec provider identity; raises if the tool
        has no trusted installation (no silent fallback, ADR-005).
        """
        provider = spec.get("provider")
        if not isinstance(provider, Mapping):
            raise ProviderBindingMismatchError("ToolSpec has no provider block")
        key = (provider.get("id"), provider.get("version"), provider.get("adapter"))
        adapter = self._installed.get(key)
        if adapter is None:
            raise ProviderNotInstalledError(
                f"No trusted installation for provider {key}; refusing silent fallback"
            )
        if provider.get("runtime") != "subprocess":
            raise ProviderBindingMismatchError("ToolSpec provider runtime is not subprocess")
        if adapter.provider() != dict(provider):
            raise ProviderBindingMismatchError(
                "Installed adapter provider block differs from ToolSpec provider"
            )
        return adapter

    def is_installed(self, spec: Mapping[str, Any]) -> bool:
        provider = spec.get("provider") or {}
        return (provider.get("id"), provider.get("version"),
                provider.get("adapter")) in self._installed
